/**
 * Metrics Collector for TeammateTool operations
 *
 * Collects and aggregates metrics for monitoring and
 * observability of teammate bridge operations.
 *
 * @module @claude-flow/teammate-plugin/utils/metrics-collector
 */

import type { BridgeMetrics, MetricSnapshot } from '../types.js';

/**
 * Metrics collector with counters, gauges, and histograms
 */
export class MetricsCollector {
  private metrics: BridgeMetrics;
  private readonly maxHistogramSize = 1000;

  constructor() {
    this.metrics = this.createEmptyMetrics();
  }

  private createEmptyMetrics(): BridgeMetrics {
    return {
      teamsCreated: 0,
      teammatesSpawned: 0,
      messagesSent: 0,
      broadcastsSent: 0,
      plansSubmitted: 0,
      plansApproved: 0,
      plansRejected: 0,
      swarmsLaunched: 0,
      delegationsGranted: 0,
      errorsCount: 0,
      activeTeams: 0,
      activeTeammates: 0,
      pendingPlans: 0,
      mailboxSize: 0,
      spawnLatency: [],
      messageLatency: [],
      planApprovalLatency: [],
      rateLimitHits: 0,
      rateLimitBlocks: 0,
      healthChecksPassed: 0,
      healthChecksFailed: 0,
      startedAt: new Date(),
      lastActivityAt: new Date(),
    };
  }

  /**
   * Increment a counter metric
   */
  increment(metric: keyof BridgeMetrics, amount = 1): void {
    const value = this.metrics[metric];
    if (typeof value === 'number') {
      (this.metrics[metric] as number) += amount;
    }
    this.metrics.lastActivityAt = new Date();
  }

  /**
   * Decrement a counter metric
   */
  decrement(metric: keyof BridgeMetrics, amount = 1): void {
    const value = this.metrics[metric];
    if (typeof value === 'number') {
      (this.metrics[metric] as number) = Math.max(0, (value as number) - amount);
    }
  }

  /**
   * Set a gauge metric to a specific value
   */
  set(metric: keyof BridgeMetrics, value: number): void {
    if (typeof this.metrics[metric] === 'number') {
      (this.metrics[metric] as number) = value;
    }
  }

  /**
   * Record a latency measurement
   */
  recordLatency(metric: 'spawnLatency' | 'messageLatency' | 'planApprovalLatency', ms: number): void {
    const arr = this.metrics[metric];
    if (arr.length >= this.maxHistogramSize) {
      arr.shift(); // Remove oldest
    }
    arr.push(ms);
  }

  /**
   * Get a snapshot of current metrics
   */
  getSnapshot(): MetricSnapshot {
    const elapsed = (Date.now() - this.metrics.startedAt.getTime()) / 1000;
    return {
      timestamp: new Date(),
      metrics: { ...this.metrics },
      rates: {
        messagesPerSecond: elapsed > 0 ? this.metrics.messagesSent / elapsed : 0,
        spawnsPerMinute: elapsed > 0 ? (this.metrics.teammatesSpawned / elapsed) * 60 : 0,
        errorRate: this.metrics.messagesSent > 0
          ? this.metrics.errorsCount / this.metrics.messagesSent
          : 0,
      },
    };
  }

  /**
   * Calculate percentile for latency metrics
   */
  getPercentile(metric: 'spawnLatency' | 'messageLatency' | 'planApprovalLatency', percentile: number): number {
    const arr = [...this.metrics[metric]].sort((a, b) => a - b);
    if (arr.length === 0) return 0;
    const index = Math.ceil((percentile / 100) * arr.length) - 1;
    return arr[Math.max(0, index)];
  }

  /**
   * Get average latency for a metric
   */
  getAverageLatency(metric: 'spawnLatency' | 'messageLatency' | 'planApprovalLatency'): number {
    const arr = this.metrics[metric];
    if (arr.length === 0) return 0;
    return arr.reduce((sum, val) => sum + val, 0) / arr.length;
  }

  /**
   * Reset all metrics
   */
  reset(): void {
    this.metrics = this.createEmptyMetrics();
  }

  /**
   * Get raw metrics object (for testing)
   */
  getRawMetrics(): BridgeMetrics {
    return { ...this.metrics };
  }
}

/**
 * Rate Limiter for TeammateTool operations
 *
 * Implements sliding window rate limiting to prevent abuse
 * and ensure fair resource distribution across teammates.
 *
 * @module @claude-flow/teammate-plugin/utils/rate-limiter
 */

import type { RateLimitConfig, RateLimitState } from '../types.js';

/**
 * Rate limiter with configurable per-operation limits
 */
export class RateLimiter {
  private windows: Map<string, RateLimitState> = new Map();
  private readonly windowMs = 60000; // 1 minute window

  constructor(private config: RateLimitConfig) {}

  /**
   * Check if operation is allowed under rate limit
   */
  checkLimit(operation: keyof RateLimitConfig): boolean {
    const limit = this.config[operation];
    const now = Date.now();
    const state = this.windows.get(operation);

    if (!state || now - state.windowStart >= this.windowMs) {
      // New window
      this.windows.set(operation, {
        operation,
        count: 1,
        windowStart: now,
        blocked: false,
      });
      return true;
    }

    if (state.count >= limit) {
      state.blocked = true;
      state.nextAllowedAt = state.windowStart + this.windowMs;
      return false;
    }

    state.count++;
    return true;
  }

  /**
   * Get current state for an operation
   */
  getState(operation: string): RateLimitState | undefined {
    return this.windows.get(operation);
  }

  /**
   * Reset rate limit for an operation
   */
  reset(operation?: string): void {
    if (operation) {
      this.windows.delete(operation);
    } else {
      this.windows.clear();
    }
  }

  /**
   * Get remaining quota for an operation
   */
  getRemaining(operation: keyof RateLimitConfig): number {
    const limit = this.config[operation];
    const state = this.windows.get(operation);
    if (!state) return limit;
    return Math.max(0, limit - state.count);
  }

  /**
   * Get window duration in milliseconds
   */
  getWindowMs(): number {
    return this.windowMs;
  }

  /**
   * Check if an operation is currently blocked
   */
  isBlocked(operation: keyof RateLimitConfig): boolean {
    const state = this.windows.get(operation);
    return state?.blocked ?? false;
  }

  /**
   * Get time until rate limit resets for an operation
   */
  getTimeUntilReset(operation: keyof RateLimitConfig): number {
    const state = this.windows.get(operation);
    if (!state) return 0;
    const remaining = (state.windowStart + this.windowMs) - Date.now();
    return Math.max(0, remaining);
  }
}

/**
 * Retry utilities for TeammateTool operations
 *
 * Provides exponential backoff retry logic with
 * configurable delays and error filtering.
 *
 * @module @claude-flow/teammate-plugin/utils/retry
 */

import type { RetryConfig, RetryState } from '../types.js';

/**
 * Execute a function with retry logic
 *
 * @param fn - Function to execute
 * @param config - Retry configuration
 * @param isRetryable - Optional function to determine if error is retryable
 * @returns Promise resolving to function result
 * @throws Last error if all retries exhausted
 */
export async function withRetry<T>(
  fn: () => Promise<T>,
  config: RetryConfig,
  isRetryable?: (error: Error) => boolean
): Promise<T> {
  let lastError: Error | null = null;
  let delay = config.initialDelayMs;

  for (let attempt = 1; attempt <= config.maxRetries + 1; attempt++) {
    try {
      return await fn();
    } catch (error) {
      lastError = error instanceof Error ? error : new Error(String(error));

      // Check if error is retryable
      if (isRetryable && !isRetryable(lastError)) {
        throw lastError;
      }

      // Check if we've exhausted retries
      if (attempt > config.maxRetries) {
        throw lastError;
      }

      // Wait before retrying
      await new Promise(resolve => setTimeout(resolve, delay));

      // Exponential backoff
      delay = Math.min(delay * config.backoffMultiplier, config.maxDelayMs);
    }
  }

  throw lastError;
}

/**
 * Create a retry state tracker
 */
export function createRetryState(): RetryState {
  return {
    attempt: 0,
    lastError: null,
    nextRetryAt: null,
    totalDelayMs: 0,
  };
}

/**
 * Calculate delay for a specific attempt using exponential backoff
 */
export function calculateBackoffDelay(
  attempt: number,
  config: RetryConfig
): number {
  const delay = config.initialDelayMs * Math.pow(config.backoffMultiplier, attempt - 1);
  return Math.min(delay, config.maxDelayMs);
}

/**
 * Sleep for a specified duration
 */
export function sleep(ms: number): Promise<void> {
  return new Promise(resolve => setTimeout(resolve, ms));
}

/**
 * Execute with timeout
 */
export async function withTimeout<T>(
  fn: () => Promise<T>,
  timeoutMs: number,
  timeoutError?: Error
): Promise<T> {
  return Promise.race([
    fn(),
    new Promise<never>((_, reject) =>
      setTimeout(
        () => reject(timeoutError ?? new Error(`Operation timed out after ${timeoutMs}ms`)),
        timeoutMs
      )
    ),
  ]);
}

